"use client";

import React, { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import GuessInput from "./GuessInput";
import WinModal from "./WinModal";
import LostModal from "./LostModal";

export default function Game({ initialGameId = null }) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [game, setGame] = useState(null);
  const [showWin, setShowWin] = useState(false);
  const [showLost, setShowLost] = useState(false);

  async function createNewGame() {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch("http://127.0.0.1:8000/game/new/", {
        method: "POST",
        headers: { Accept: "application/json" },
      });

      if (!res.ok) {
        const errJson = await res.json().catch(() => null);
        throw new Error((errJson && errJson.error) || `HTTP ${res.status}`);
      }

      const data = await res.json();
      setGame(data);
      // navigate to the game URL so the page reflects the new game's id
      try {
        if (data && data.game_id) router.push(`/game/${data.game_id}`);
      } catch (e) {
        // ignore navigation errors
      }
    } catch (e) {
      setError(String(e.message || e));
    } finally {
      setLoading(false);
    }
  }

  async function fetchGameState(id) {
    if (!id) return;
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(`http://127.0.0.1:8000/game/${id}/`, {
        method: "GET",
        headers: { Accept: "application/json" },
      });

      if (!res.ok) {
        const errJson = await res.json().catch(() => null);
        throw new Error((errJson && errJson.error) || `HTTP ${res.status}`);
      }

      const data = await res.json();
      setGame(data);
    } catch (e) {
      setError(String(e.message || e));
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    if (game) {
      const state = String(game.current_state || "").toLowerCase();
      if (state === "w" || state === "won") {
        setShowWin(true);
      } else {
        setShowWin(false);
      }
      if (state === "l" || state === "lost") {
        setShowLost(true);
      } else {
        setShowLost(false);
      }
    }
  }, [game]);

  useEffect(() => {
    if (initialGameId) {
      fetchGameState(initialGameId);
    }
  }, [initialGameId]);

  return (
    <div>
      <div style={{ marginTop: 16 }}>
        <button onClick={createNewGame} disabled={loading}>
          {loading ? "Starting..." : "Start New Game"}
        </button>
      </div>

      {error && (
        <div style={{ color: "red", marginTop: 12 }}>Error: {error}</div>
      )}

      {game && (
        <div style={{ marginTop: 12 }}>
          <strong>Game started:</strong>
          <div>{game.guessed_word || game.word}</div>
          <div>Guesses Left: {game.guesses_left ?? game.max_incorrect_guesses}</div>
          <GuessInput
            gameId={game.game_id || initialGameId}
            disabled={!!(game.current_state && (String(game.current_state).toLowerCase() === "w" || String(game.current_state).toLowerCase() === "l"))}
            onUpdate={(data) => setGame((prev) => ({ ...(prev || {}), ...data }))}
          />
            <div style={{ marginTop: 8 }}>
              <div style={{ marginBottom: 6 }}>word:</div>
              <div style={{ display: "flex", gap: 8 }}>
                {((game.guessed_word && game.guessed_word.length > 0 ? game.guessed_word : game.word) || "").split("").map((ch, i) => (
                  <div
                    key={i}
                    style={{
                      minWidth: 32,
                      height: 40,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      border: "1px solid #ccc",
                      borderRadius: 4,
                      fontSize: 18,
                      background: "#fff",
                    }}
                  >
                    {ch}
                  </div>
                ))}
              </div>
            </div>
        </div>
      )}
      {showWin && (
        <WinModal
          message="Congratulations. You have won the game"
          onClose={() => setShowWin(false)}
        />
      )}
      {showLost && (
        <LostModal
          message="Sorry, you lost the game"
          onClose={() => setShowLost(false)}
        />
      )}
    </div>
  );
}
